begin;
set local search_path=public,extensions;
select no_plan();
select ok(public.valid_music_excerpt('{"start":10,"end":19}'),'valid intended moment');
select ok(not public.valid_music_excerpt('null'),'explicit null rejected');
select ok(not public.valid_music_excerpt('{"start":10,"end":19,"secret":"private"}'),'unknown moment fields rejected');
select ok(not public.valid_music_excerpt('{"start":10,"end":9}'),'reversed moment rejected');
select ok(not public.valid_music_excerpt('{"start":0,"end":86401}'),'unbounded moment rejected');
select ok(not public.valid_music_excerpt('{"start":0.5,"end":10}'),'fractional moment rejected');
select ok(public.valid_journal_appearance('{"font":"literary"}'),'literary font accepted');
select ok(public.valid_journal_appearance('{"font":"humanist"}'),'humanist font accepted');
select ok(public.valid_journal_appearance('{"font":"mono"}'),'mono font accepted');
select ok(not public.valid_journal_appearance('{"font":"url(evil)"}'),'arbitrary font code rejected');
select ok(public.valid_profile_panel('{}'),'panel defaults are opt-in');
select ok(public.valid_profile_panel('{"show_count":true,"interests":["Books"],"link":"https://example.org/about"}'),'deliberate public details accepted');
select ok(not public.valid_profile_panel('{"role":"owner"}'),'privilege fields rejected');
select ok(not public.valid_profile_panel('{"link":"javascript:alert(1)"}'),'active links rejected');
select ok(not public.valid_profile_panel('{"link":"https://secret@example.org"}'),'credentials rejected');
select ok(not public.valid_profile_panel('{"interests":["<script>"]}'),'markup rejected');
insert into auth.users(id) values ('12000000-0000-0000-0000-000000000001'),('12000000-0000-0000-0000-000000000002');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"12000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select lives_ok($$insert into public.journal_entries(id,title,body,music) values ('22000000-0000-0000-0000-000000000001','Synthetic moment','Private','{"provider":"spotify","kind":"track","id":"4uLU6hMCjMI75M1A2tKUQC","share":false,"excerpt":{"start":10,"end":19}}')$$,'private moment saves');
select throws_ok($$insert into public.public_stories(id,user_id,title,body,music) values ('22000000-0000-0000-0000-000000000001','12000000-0000-0000-0000-000000000001','Public','Approved','{"provider":"spotify","kind":"track","id":"4uLU6hMCjMI75M1A2tKUQC","excerpt":{"start":10,"end":19}}')$$,'23514',null,'unapproved moment is blocked');
update public.journal_entries set music=jsonb_set(music,'{share}','true') where id='22000000-0000-0000-0000-000000000001';
select lives_ok($$insert into public.public_stories(id,user_id,title,body,public_category,music) values ('22000000-0000-0000-0000-000000000001','12000000-0000-0000-0000-000000000001','Public','Approved','Study','{"provider":"spotify","kind":"track","id":"4uLU6hMCjMI75M1A2tKUQC","excerpt":{"start":10,"end":19}}')$$,'approved moment and newer public category save');
select throws_ok($$update public.public_stories set music=jsonb_set(music,'{excerpt,end}','30') where id='22000000-0000-0000-0000-000000000001'$$,'23514',null,'unapproved public moment change rejected');
select lives_ok($$insert into public.public_profiles(username,display_name,public_panel) values ('studio_fixture','Synthetic','{"show_count":true}')$$,'owner saves hidden panel');
select lives_ok($$insert into public.user_settings(user_id,theme_id,appearance) values ('12000000-0000-0000-0000-000000000001','warm-sepia','{"font":"mono"}')$$,'account saves new appearance');
select set_config('request.jwt.claims','{"sub":"12000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
select is((select count(*)::int from public.journal_entries where id='22000000-0000-0000-0000-000000000001'),0,'B cannot read A private music');
select is((select count(*)::int from public.public_profiles where username='studio_fixture'),0,'B cannot read hidden profile panel');
select is((with changed as (update public.public_profiles set public_panel='{}' where username='studio_fixture' returning username) select count(*)::int from changed),0,'B cannot edit A profile panel');
reset role;
set local role anon;
select is((select count(*)::int from public.public_profiles where username='studio_fixture'),0,'anonymous cannot read hidden profile panel');
select is((select music->'excerpt' from public.public_stories where id='22000000-0000-0000-0000-000000000001'),'{"start":10,"end":19}'::jsonb,'anonymous sees approved moment only');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"12000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
update public.public_profiles set visible=true where username='studio_fixture';
reset role;
set local role anon;
select is((select public_panel->'show_count' from public.public_profiles where username='studio_fixture'),'true'::jsonb,'anonymous sees only explicitly visible panel');
select throws_ok($$select user_id from public.public_profiles where username='studio_fixture'$$,'42501',null,'hidden ownership remains inaccessible');
reset role;
select * from finish();
rollback;
